import {expect} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import {writeFileSync} from 'node:fs';
import {installCustomerLinks,startCustomerLinkService} from './install-customer-links.mjs';
let service;const checks=[];
export async function captureLiveStore(page,mode){
 service??=await startCustomerLinkService({liveStore:true,staffTeam:true,ordering:true});await service.reset();const here=new URL(page.url()),at=here.pathname.lastIndexOf('/app/');if(at<0)throw Error('Missing app base');const app=here.pathname.slice(0,at+5),base=app.slice(0,-4);
 await service.staffScene(app);await service.liveSale('48320');await service.liveSale('31200',12);await service.liveSale('33320',13);await service.liveScene();await service.liveQuestion('আমাকে আরও একটু সময় দিন। Please allow a little more time.');await service.publishShop('T-1');await service.publishShop('T-2','T'.repeat(43));
 await page.goto(new URL(app+'?flags=liveStore',here.origin).href);await installCustomerLinks(page);await page.evaluate(v=>window.miseCustomerLinkTest.initialize(v),service.config());await page.goto(new URL(app+(mode==='all'?'outlets':'live')+'?flags=liveStore',here.origin).href);await expect(page.locator('.live-kpis')).toBeVisible();if(mode==='question'){await page.locator('.live-attention').getByRole('button').first().click();await expect(page.getByRole('dialog')).toContainText('Please allow a little more time.');}
 await page.evaluate(()=>document.fonts.ready);const result=await new AxeBuilder({page}).withTags(['wcag2a','wcag2aa','wcag21aa','wcag22aa']).analyze(),overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),assets=await page.locator('.live-store img').evaluateAll(images=>images.filter(img=>img.getBoundingClientRect().width>0).map(img=>({file:img.getAttribute('src').split('/').at(-1),width:img.getBoundingClientRect().width,height:img.getBoundingClientRect().height,naturalWidth:img.naturalWidth,naturalHeight:img.naturalHeight})));
 for(const asset of assets){expect(asset.naturalWidth).toBeGreaterThan(0);expect(asset.naturalHeight).toBeGreaterThan(0);expect(asset.width).toBe(asset.naturalWidth);expect(asset.height).toBe(asset.naturalHeight);}expect(result.violations).toEqual([]);expect(overflow).toBe(false);checks.push({mode,width:page.viewportSize().width,assets,overflow,violations:result.violations.map(v=>({id:v.id,impact:v.impact})),base});await page.evaluate(()=>{if(document.activeElement instanceof HTMLElement)document.activeElement.blur();});await page.addStyleTag({content:'.app-skip,.app-bottom-nav{visibility:hidden!important}'});
}
export async function closeLiveStoreVisual(){if(service){await service.close();service=undefined;}if(checks.length)writeFileSync('.private/m36-visual-proof.json',JSON.stringify(checks,null,2)+'\n');}
